#!/usr/bin/env node
/**
 * What `@zodiacs/engine` actually costs in a browser bundle.
 *
 * The engine page publishes a size, and a size published without a method is
 * not a measurement. This bundles the installed package the way a consumer
 * would — esbuild, browser platform, minified, ephemeris included, because the
 * ephemeris is what actually ships — and writes the result to
 * `src/data/engine-bundle.json`, which the page reads.
 *
 * Two entries are measured: the natal path on its own, and the natal path plus
 * the optional local-time resolver, so the cost of the option is visible
 * rather than folded into one number.
 *
 *   node scripts/measure-engine-bundle.mjs           # write
 *   node scripts/measure-engine-bundle.mjs --check   # fail on drift
 *
 * `--check` allows a small tolerance. esbuild and zlib are deterministic for a
 * fixed input and version, but the pinned version moves with a dependency
 * bump, and failing a build over 40 bytes would only teach people to ignore
 * the gate. A real change in what the package costs is far larger than that.
 */
import { brotliCompressSync, gzipSync } from 'node:zlib';
import { readFileSync, writeFileSync } from 'node:fs';
import * as esbuild from 'esbuild';

const OUT = 'src/data/engine-bundle.json';
/** KB means 1024 bytes here, matching scripts/report-bundles.mjs. */
const KB = 1024;
const TOLERANCE_KB = 1;

/**
 * Three entries, because "+ geo" is two different numbers and labelling one of
 * them as the other overstates what local-time resolution costs. `resolveBirth`
 * is the time resolver on its own; the namespace import also pins the GeoNames
 * HTTP client that shares the entry point, which is 1.2 KB gzipped more and,
 * more to the point, is the part that can make a network request.
 */
const ENTRIES = {
  natal: "import { natalChart } from '@zodiacs/engine';\nglobalThis.__keep = natalChart;\n",
  localTime: "import { natalChart } from '@zodiacs/engine';\nimport { resolveBirth } from '@zodiacs/engine/geo';\nglobalThis.__keep = [natalChart, resolveBirth];\n",
  geo: "import { natalChart } from '@zodiacs/engine';\nimport * as geo from '@zodiacs/engine/geo';\nglobalThis.__keep = [natalChart, geo];\n",
};

async function measure(source, name) {
  // stdin with resolveDir, not a temp file: a bare specifier has to resolve
  // from this project's node_modules, and a file in the system temp directory
  // resolves from there instead.
  const built = await esbuild.build({
    stdin: { contents: source, resolveDir: process.cwd(), sourcefile: `${name}.mjs`, loader: 'js' },
    bundle: true,
    format: 'esm',
    platform: 'browser',
    minify: true,
    write: false,
    absWorkingDir: process.cwd(),
    logLevel: 'error',
  });
  const bytes = Buffer.from(built.outputFiles[0].contents);
  const round = (n) => Number((n / KB).toFixed(1));
  return {
    minKb: round(bytes.length),
    gzipKb: round(gzipSync(bytes, { level: 9 }).length),
    brotliKb: round(brotliCompressSync(bytes).length),
  };
}

let measured;
{
  measured = {
    note: 'Generated by scripts/measure-engine-bundle.mjs. KB is 1024 bytes.',
    // The package does not export ./package.json, so read the installed
    // manifest off disk rather than resolving a subpath it does not publish.
    engineVersion: JSON.parse(readFileSync('node_modules/@zodiacs/engine/package.json', 'utf8')).version,
    esbuildVersion: esbuild.version,
    natal: await measure(ENTRIES.natal, 'natal'),
    localTime: await measure(ENTRIES.localTime, 'localTime'),
    geo: await measure(ENTRIES.geo, 'geo'),
  };
}

if (process.argv.includes('--check')) {
  const committed = JSON.parse(readFileSync(OUT, 'utf8'));
  const problems = [];
  if (committed.engineVersion !== measured.engineVersion) {
    problems.push(`engineVersion: committed ${committed.engineVersion}, installed ${measured.engineVersion}`);
  }
  for (const entry of ['natal', 'localTime', 'geo']) {
    for (const key of ['minKb', 'gzipKb', 'brotliKb']) {
      const was = committed[entry]?.[key];
      const now = measured[entry][key];
      if (typeof was !== 'number' || Math.abs(was - now) > TOLERANCE_KB) {
        problems.push(`${entry}.${key}: committed ${was}, measured ${now}`);
      }
    }
  }
  if (problems.length) {
    console.error('engine-bundle: drift beyond tolerance\n  ' + problems.join('\n  '));
    console.error(`\nRe-run: node ${process.argv[1].split('/').pop()}`);
    process.exit(1);
  }
  console.log(`engine-bundle: within ${TOLERANCE_KB} KB of the committed measurement`
    + ` (natal ${measured.natal.gzipKb} KB gzip, esbuild ${measured.esbuildVersion})`);
} else {
  writeFileSync(OUT, `${JSON.stringify(measured, null, 2)}\n`);
  console.log(`engine-bundle: wrote ${OUT}`);
  for (const [label, key] of [['natal      ', 'natal'], ['+ time     ', 'localTime'], ['+ geo (all)', 'geo']]) {
    const e = measured[key];
    console.log(`  ${label}  min ${e.minKb} KB  gzip ${e.gzipKb} KB  brotli ${e.brotliKb} KB`);
  }
}
